now=datetime.datetime.now(datetime.timezone.utc).isoformat()
paths=[P/'EXECUTION_PROTOCOL.json',P/'source_material'/'reductions'/'paper'/'forests.tex',BASE/'BOARD.md',BASE/'claude'/'B02'/'STREAM_NOTES.md',BASE/'claude'/'B03'/'STREAM_NOTES.md',ROOT/'runs'/'20261011T223308Z-fleet05-A009-fractional-incidence-optimization'/'INCIDENCE_OPTIMIZATION.tex']
