def claim(cid,statement,hyp,source,deps,status,review=[]):
 d={'claim_id':cid,'version':1,'exact_statement':statement,'hypotheses':hyp,'statement_sha256':hashlib.sha256(statement.encode()).hexdigest(),'contributors':['A009'],'proof_source':source,'proof_dependencies':deps,'review_records':review,'status':status,'supersedes':[],'refutes':[],'first_unproved_line':None,'next_consumers':['A006','A007','A010','A014','A086','A094','B02','B03','B20']}
 assert set(d)==set(protocol['required_per_run']['claim_fields'])
 return d
