deps=[{'source':str(P/'source_material'/'reductions'/'paper'/'forests.tex'),'locator':'eq:forestpacking, eq:forestconditioning, eq:forestcost, thm:posteriorforest','sha256':forestsha,'status':'SOURCE_COMPLETE_BASELINE'}]
claims=[claim('A009-AFFINE-PLANE-FULL-PIJ-CERTIFICATE','For every prime power q>=16, the Boolean OR of all positive affine-line conjunctions on q^2 fair coordinates has exactly those line gates as its prime implicants. With uniform global lambda_l=1/(q+1), pi_l=2^-q, M_l=1 and any fixed line orders, the explicit one-line-when-possible/source-SCC-otherwise deterministic actual partition-forest law has complete conditioned residual R<=186791 I/13540<14I. No actual-run posterior entropy credit is required. The scalar linear-hypergraph transfer inequality (T) in REPORT.md holds for every distinct positive equal-width gate table with pairwise intersections at most one; it is not asserted O(I) at arbitrary density. The affine result is a full PI-J upper certificate, not an optimal value or a universal FEI claim.',['uniform Boolean cube','q prime power >=16','all positive line prime implicants; one global packing vector','actual terminating partition forests','bits; gamma=6/5'],{'path':str(R/'REPORT.md'),'locators':'Derivation 2-6','companion':str(R/'FOREST_TRANSFER.tex')},deps,'AUTHOR_PROVED_EXACTLY_CHECKED_PENDING_INDEPENDENT_REVIEW')]
orig=json.loads((a7/'CLAIMS.json').read_text())
orig=next(x for x in orig if x['claim_id']=='A007-PIJ-ACTIVATION-CLOSURE-AND-NORMALIZER-DIAGNOSTIC')
review={'reviewer':'A009','source_claim_id':orig['claim_id'],'source_version':orig['version'],'source_statement_sha256':orig['statement_sha256'],'scope':'Only the affine-plane retained-normalizer clause in derivation A2; not the bundled activated-tribes theorem','verdict':'ACCEPT_AT_STATED_SCOPE','supplied_substantive_repair':False,'method':'Independent reconstruction of row-mass Holder/Jensen, root-product lower bound and total-scale monotonicity','source':str(R/'REPORT.md')}
claims.append(claim('A009-SCOPED-REVIEW-A007-AFFINE-NORMALIZER','The affine-plane retained-normalizer clause of A007-PIJ-ACTIVATION-CLOSURE-AND-NORMALIZER-DIAGNOSTIC v1 holds: for all prime powers q>=16, all positive feasible global weights and all pivotal tie rules, P+v log2 Z >= [7 log2((q+1)/2)-5]I. This review does not assert acceptance of the bundled activation theorem or a lower bound for whole-set PI-J.',['source exact affine-plane scope','uniform Boolean cube','positive incidence vector','bits'],{'path':str(R/'REPORT.md'),'locator':'Derivation 1','original':str(a7/'REPORT.md')},[{'claim_id':orig['claim_id'],'version':1,'statement_sha256':orig['statement_sha256'],'used_scope':'affine normalization clause only; independently reconstructed here'}],'SCOPED_INDEPENDENT_REVIEW_COMPLETE_LOCALLY',[review]))
