progress={'protocol_revision':protocol['revision'],'run_id':R.name,'stream':'B02','packet_id':'A009','gap_id':'G-J-COST','attempt_id':'A009-PIJ-affine-full-transfer-v1','method':'actual one-line/source-SCC forest; ideal indicator-sum spectrum plus fully paid L2 error; rational endpoint certificate; scoped independent normalizer review','mathematical_delta':'Affine-plane coordinatewise lower pressure is not a PI-J obstruction: all-q>=16 complete residual <=186791/13540 I<14I with one uniform packing vector. Generic equal-width linear-hypergraph full cost-transfer inequality; A007 retained-normalizer clause accepted at scope.','deliverable_status':'COMPLETE_LOCAL_ARTIFACTS_PENDING_SUPERVISOR_COPY','mathematical_status':'SCOPED_SOURCE_COMPLETE_PROOF_PENDING_INDEPENDENT_REVIEW; FULL_FEI_OPEN','claim_versions_used':deps+[{'claim_id':orig['claim_id'],'version':1,'statement_sha256':orig['statement_sha256'],'scope':'Independent review only; not a proof premise for positive upper theorem'}],'claims_created_or_changed':[x['claim_id']+'@1' for x in claims],'source_artifacts':['REPORT.md','CLAIMS.json','FOREST_TRANSFER.tex','FROZEN_SPEC.json','code/check.py','out/CHECK.json','out/TRACES_q2.json','out/TRACES_q3.json','out/PILOT_CORRECTION.json','out/PILOT_SLOW.json','out/SOURCES.json'],'next_consumers':['A006','A007','A010','A014','A086','A094','B02','B03','B20'],'next_action':'A086/A094 review full forest and transfer; A014/B03 substitute normalized interference/error bounds into (T) at arbitrary density instead of repeating affine-plane calibration.','stagnant_substantive_attempts':0,'blockers':['Full transfer-error budget is not influence-paid for arbitrary dense prime tables.','New continuation proof awaits independent review and registry adoption.'],'packet_ids':['A009']}
assert set(progress)==set(x.split(' (')[0] for x in protocol['required_per_run']['progress_fields'])
for n in ['PROGRESS.json','PACKET_DELTA.json']:(R/n).write_text(json.dumps(progress,indent=2),encoding='utf-8')
report=(R/'REPORT.md').read_text()
for f in protocol['required_per_run']['report_fields']:assert '## '+f in report
if 'Observed final checker:' not in report:
 marker='## proof dependencies and changed downstream conclusions'
